import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Frequency table over compressed values; distinct counts the values present in the window.
        long[] keys = a.clone();
        Arrays.sort(keys);
        int m = 0;
        for (int i = 0; i < n; i++) if (i == 0 || keys[i] != keys[i - 1]) keys[m++] = keys[i];
        int[] id = new int[n], counts = new int[m];
        for (int i = 0; i < n; i++) id[i] = Arrays.binarySearch(keys, 0, m, a[i]);
        long total = 0, best = 0;
        int distinct = 0;
        boolean found = false;
        for (int i = 0; i < n; i++) {
            total += a[i];
            if (counts[id[i]]++ == 0) distinct++;
            if (i >= k) {
                total -= a[i - k];
                if (--counts[id[i - k]] == 0) distinct--;
            }
            if (i + 1 >= k && distinct == k) {
                best = found ? Math.max(best, total) : total;
                found = true;
            }
        }
        System.out.println(found ? best : -1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Frequency table over compressed values; distinct counts the values present in the window.
	keys := slices.Clone(a)
	slices.Sort(keys)
	keys = slices.Compact(keys)
	id := make([]int, n)
	counts := make([]int, len(keys))
	for i, v := range a {
		id[i], _ = slices.BinarySearch(keys, v)
	}
	total, best, distinct, found := 0, 0, 0, false
	for i := 0; i < n; i++ {
		total += a[i]
		if counts[id[i]] == 0 {
			distinct++
		}
		counts[id[i]]++
		if i >= k {
			total -= a[i-k]
			counts[id[i-k]]--
			if counts[id[i-k]] == 0 {
				distinct--
			}
		}
		if i+1 >= k && distinct == k {
			if !found || total > best {
				best = total
			}
			found = true
		}
	}
	if found {
		fmt.Println(best)
	} else {
		fmt.Println(-1)
	}
}
